import{_ as o,c as e,a2 as t,o as r}from"./chunks/framework.D7kq4b6j.js";const g=JSON.parse('{"title":"长音","description":"","frontmatter":{},"headers":[],"relativePath":"docs/日本語学習/五十音/7-长音.md","filePath":"docs/日本語学習/五十音/7-长音.md","lastUpdated":1723443308000}'),n={name:"docs/日本語学習/五十音/7-长音.md"};function s(i,a,l,h,p,c){return r(),e("div",null,a[0]||(a[0]=[t('<h1 id="长音" tabindex="-1">长音 <a class="header-anchor" href="#长音" aria-label="Permalink to &quot;长音&quot;">​</a></h1><p>要唸長音時，只需要將前一個字母的發音拉長即可。 平假名長音沒有特別的輸入方式，按照原本的單字輸入即可。</p><h2 id="出现的情况" tabindex="-1">出现的情况 <a class="header-anchor" href="#出现的情况" aria-label="Permalink to &quot;出现的情况&quot;">​</a></h2><h3 id="两个相同的发音在一起" tabindex="-1">两个相同的发音在一起 <a class="header-anchor" href="#两个相同的发音在一起" aria-label="Permalink to &quot;两个相同的发音在一起&quot;">​</a></h3><blockquote><p>●當あ（a）、い（i）、う（u）、え（e）、お（o）這五個母音重複時，就要念成長音。</p></blockquote><p>あ（a）段長音：在字母後面加上「あ（a）」。例如：お<strong>かあ</strong>さん（o+k<strong>a+a</strong>+sa+n）</p><p>い（i）段長音：在字母後面加上「い（i）」。例如：いいね（<strong>i+i</strong>+ne）</p><p>う（u）段長音：在字母後面加上「う（u）」。例如：<strong>くう</strong>き（k<strong>u+u</strong>+ki）</p><p>え（e）段長音：在字母後面加上「え（e）」或「い（i）」。例如：<strong>ええ</strong>（<strong>e+e</strong>）、<strong>えい</strong>ご（<strong>e+i</strong>+go）</p><p>お（o）段長音：在字母後面加上「う（u）」或「お（o）」。例如：<strong>とう</strong>きょう（t<strong>o+u</strong>+ky<strong>o+u</strong>）、<strong>とお</strong>い（t<strong>o+o</strong>+i）</p><h3 id="假名后面-同段元音" tabindex="-1">假名后面+同段元音 <a class="header-anchor" href="#假名后面-同段元音" aria-label="Permalink to &quot;假名后面+同段元音&quot;">​</a></h3><h3 id="お段假名-う" tabindex="-1">お段假名+う <a class="header-anchor" href="#お段假名-う" aria-label="Permalink to &quot;お段假名+う&quot;">​</a></h3><h3 id="う段假名-い" tabindex="-1">う段假名+い <a class="header-anchor" href="#う段假名-い" aria-label="Permalink to &quot;う段假名+い&quot;">​</a></h3><p>更多：</p><p><a href="https://www.sigure.tw/learn-japanese/basic/50/dakuon-youon-chouon-sokuon#%E9%95%B7%E9%9F%B3" target="_blank" rel="noreferrer">https://www.sigure.tw/learn-japanese/basic/50/dakuon-youon-chouon-sokuon#長音</a></p><p><a href="https://coolcode.org/2017/09/17/my-japanese-learning-notes-5/#%E7%89%87%E5%81%87%E5%90%8D%E5%8D%95%E8%AF%8D%E4%B8%AD%E7%9A%84%E9%95%BF%E9%9F%B3" target="_blank" rel="noreferrer">https://coolcode.org/2017/09/17/my-japanese-learning-notes-5/#片假名单词中的长音</a></p>',16)]))}const u=o(n,[["render",s]]);export{g as __pageData,u as default};
